ards -->\n  <meta property=\"og:type\" content=\"website\">\n  <meta property=\"og:url\" content=\"https://seokit.globalcorehub.com/vi/keyword-density-analyzer\">\n  <meta property=\"og:title\" content=\"Keyword Density Trình kiểm tra | SeoKit Studio\">\n  <meta property=\"og:description\" content=\"Keyword Density: Công cụ trực tuyến siêu tốc và bảo mật, chạy cục bộ 100% trong trình duyệt không qua máy chủ.\">\n  <meta property=\"og:site_name\" content=\"SeoKit Studio\">\n  <meta property=\"og:locale\" content=\"vi_VN\">\n  <meta property=\"og:image\" content=\"https://seokit.globalcorehub.com/og-image.svg\">\n  <meta property=\"og:image:width\" content=\"1200\">\n  <meta property=\"og:image:height\" content=\"630\">\n  <meta property=\"og:image:alt\" content=\"SeoKit Studio\">\n\n  <!-- Twitter Social Cards -->\n  <meta name=\"twitter:card\" content=\"summary_large_image\">\n  <meta name=\"twitter:title\" content=\"Keyword Density Trình kiểm tra | SeoKit Studio\">\n  <meta name=\"twitter:description\" content=\"Keyword Density: Công cụ trực tuyến siêu tốc và bảo mật, chạy cục bộ 100% trong trình duyệt không qua máy chủ.\">\n  <meta name=\"twitter:image\" content=\"https://seokit.globalcorehub.com/og-image.svg\">\n\n  <!-- Multi-Theme Typography Imports (JetBrains Mono, Plus Jakarta Sans, Space Grotesk) -->\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n  <link href=\"https://fonts.googleapis.com/css2?family=JetBrains+Mono:wght@400;500;600;700;800&family=Plus+Jakarta+Sans:wght@400;500;600;700;800&family=Space+Grotesk:wght@500;600;700&display=swap\" rel=\"stylesheet\">\n  \n\n  <!-- Immediate Zero-FOUC Theme Initializer -->\n  <script>\n    (function() {\n      try {\n        var t = 'terminal_dev';\n        document.documentElement.setAttribute('data-theme', t);\n        if (t === 'swiss_minimal' || t === 'apple_bento_glass') {\n          document.documentElement.classList.remove('dark');\n        } else {\n          document.documentElement.classList.add('dark');\n        }\n      } catch (e) {}\n    })();\n  </script>\n\n  <!-- Tailwind CSS Core -->\n  <script src=\"https://cdn.tailwindcss.com\"></script>\n  <script>\n    tailwind.config = {\n      darkMode: 'class',\n      theme: {\n        extend: {\n          colors: {\n            brand: '#10b981'\n          }\n        }\n      }\n    }\n  </script>\n\n  <!-- Theme Specific & Dynamic Multi-Theme Styles -->\n  <style>\n    body { font-family: 'JetBrains Mono', monospace; }\n    \n        pre, code, kbd { font-family: 'JetBrains Mono', monospace; }\n        ::-webkit-scrollbar { width: 6px; height: 6px; }\n        ::-webkit-scrollbar-track { background: #0c0e14; }\n        ::-webkit-scrollbar-thumb { background: #1e2333; border-radius: 3px; }\n        ::-webkit-scrollbar-thumb:hover { background: #10b981; }\n        .terminal-dot-red { background-color: #ff5f56; }\n        .terminal-dot-yellow { background-color: #ffbd2e; }\n        .terminal-dot-green { background-color: #27c93f; }\n        \n\n    /* Dynamic Multi-Theme Overrides */\n    html[data-theme=\"terminal_dev\"] body {\n      font-family: 'JetBrains Mono', monospace !important;\n      background-color: #0c0e14 !important;\n      color: #e2e8f0 !important;\n    }\n    html[data-theme=\"terminal_dev\"] .bg-\\[\\#0c0e14\\] { background-color: #0c0e14 !important; }\n    html[data-theme=\"terminal_dev\"] header,\n    html[data-theme=\"terminal_dev\"] .bg-\\[\\#11141d\\] { background-color: #11141d !important; }\n    html[data-theme=\"terminal_dev\"] .border-\\[\\#1e2333\\] { border-color: #1e2333 !important; }\n    html[data-theme=\"terminal_dev\"] .text-\\[\\#10b981\\] { color: #10b981 !important; }\n    html[data-theme=\"terminal_dev\"] .bg-\\[\\#10b981\\] { background-color: #10b981 !important; color: #000000 !important; }\n    html[data-theme=\"terminal_dev\"] .bg-\\[\\#10b981\\]\\/10 { background-color: rgba(16, 185